from typing import Optional

from taf.sbts.oam.coam.admin import admin
from taf.sbts.oam.coam.admin.exceptions import AliasInUse

from ta_logcollector.logger import get_net_logger


class AdminInterface:
    def __init__(
        self,
        log_host: str,
        log_port: int,
        host: str,
        username: str = "Nemuadmin",
        password: str = "nemuuser",
        alias: str = "default",
        remote_host: Optional[str] = None,
        **kwargs: dict,
    ) -> None:
        """
        Get BTS information via admin library
        :param log_host: logger host
        :param log_port: logger port
        :param host: BTS host IP address
        :param username: BTS username
        :param password: BTS password
        :param alias: admin instance alias
        :remote_host: remote host address
        """
        host_mapper = {"192.168.255.1": "192.168.255.129", "192.168.255.7": "192.168.255.119"}
        self._logger = get_net_logger(log_host, log_port, "{}_{}".format("admin_", log_host))
        self._alias = alias
        self._admin = admin()
        self._host = host_mapper.get(host, host)
        self._username = username
        self._password = password
        self._connection = None
        self._remote_host = remote_host
        self.kwargs = kwargs
        self._logger.info(
            f"AdminInterface initialized with alias: {self._alias}, {self._host}, {self._username}, {self._password}, "
            f"{self._remote_host}, {self.kwargs}"
        )

    def __enter__(self) -> "AdminInterface":
        self.setup_admin()
        return self

    def __exit__(
        self, exc_type: Optional[type[BaseException]], exc_val: Optional[BaseException], exc_tb: Optional
    ) -> None:
        self.teardown_admin()

    def setup_admin(self) -> None:
        if not self._connection:
            self._logger.debug(f"Establishing admin connection via SSH tunnel to host {self._remote_host}")
            try:
                self._connection = self._admin.setup_admin(
                    alias=self._alias,
                    bts_host=self._host,
                    username=self._username,
                    password=self._password,
                    remote_host=self._remote_host,
                    **self.kwargs,
                )
            except AliasInUse:
                self._logger.error(
                    "Alias {} in use. " "Trying to teardown admin connection and setup again".format(self._alias)
                )
                self._admin.teardown_admin(alias=self._alias)
                self._connection = self._admin.setup_admin(
                    alias=self._alias,
                    bts_host=self._host,
                    username=self._username,
                    password=self._password,
                    remote_host=self._remote_host,
                    **self.kwargs,
                )
            except Exception as e:
                self._logger.exception(f"Admin setup failed: {e}")
                raise

    def teardown_admin(self) -> None:
        self._logger.debug(f"Teardown admin instance with alias {self._alias}")
        if self._connection:
            self._admin.teardown_admin(alias=self._alias)

    def get_gnb_id(self) -> int:
        """Get gNB id"""
        self._logger.info(f"Getting gNB id from alias: {self._alias}")
        bts_info = self._get_bts_info()
        return bts_info.get("nrBtsId")

    def get_cells(self) -> list[dict,]:
        """Get cells information like global cell id, PCI and status"""
        self._logger.info(f"Getting cells information from alias: {self._alias}")
        cells = []
        bts_info = self._get_bts_info()
        for cell in bts_info["cells"]["nr"]:
            cells.append(
                {
                    "id": cell.get("globalCellId"),
                    "phy_cell_id": cell.get("physicalCellId"),
                    "status": cell.get("status").get("operationalState"),
                }
            )
        return cells

    def _get_bts_info(self) -> dict:
        return self._connection.get_bts_info()
